import java.sql.*;import java.util.*;import java.nio.file.*;import com.alibaba.fastjson2.*;
/** Ordinary set-frontier JDBC reference; preserves original SNB output contracts. */
public class SnbSetSql {
 public interface RegionBoundary{void enter(Connection c)throws Exception;void leave(Connection c)throws Exception;}static RegionBoundary regionBoundary;static boolean schemaReady=false;static Set<String>knownTypes=new HashSet<>();static Map<String,String>clientRootContext=new HashMap<>();static Map<String,Long>kinds=new LinkedHashMap<>();static String url;public static void configure(Path p){query=System.getProperty("snb.query");url=System.getProperty("snb.url","jdbc:mysql://127.0.0.1:"+System.getProperty("experiment.mysql.port","55337")+"/jac_snb_six_20261020?useSSL=false&useUnicode=true&characterEncoding=UTF-8");}
 static boolean branchTopk=Boolean.getBoolean("snb.branchTopk");static boolean finiteDepth=Boolean.getBoolean("snb.finiteDepth");static long calls;static List<String> commands=new ArrayList<>();static String query=System.getProperty("snb.query");
 static String j(String a,String k){return "JSON_UNQUOTE(JSON_EXTRACT("+a+".props,'$.archetype."+k+"'))";}
 static String num(String a,String k){return "CAST("+j(a,k)+" AS SIGNED)";}
 static String marks(int n){return String.join(",",Collections.nCopies(n,"?"));}
 static String uuid(String s){if(s.indexOf('-')>=0)return s;s=String.format("%32s",s.replace("-","")).replace(' ','0');return s.substring(0,8)+"-"+s.substring(8,12)+"-"+s.substring(12,16)+"-"+s.substring(16,20)+"-"+s.substring(20);}
 static int columns(String q){if(q.startsWith("SELECT m.id"))return q.contains("ra.props")?6:4;if(q.startsWith("SELECT p.props,"))return 2;if(q.startsWith("SELECT p.id,p.person_id")||q.startsWith("SELECT p.person_id"))return 3;if(q.startsWith("SELECT CASE"))return 1;if(q.startsWith("SELECT CAST"))return 3;if(q.startsWith("SELECT DISTINCT dst")||q.startsWith("SELECT props"))return 1;throw new IllegalStateException("Undeclared typed projection: "+q);}
 static List<List<Object>> sql(Connection c,String q,Object...args)throws Exception{calls++;commands.add(q);List<List<Object>>out=new ArrayList<>();try(PreparedStatement s=c.prepareStatement(q)){for(int i=0;i<args.length;i++){Object x=args[i];if(x instanceof Long)s.setLong(i+1,(Long)x);else if(x instanceof Integer)s.setInt(i+1,(Integer)x);else s.setString(i+1,(String)x);}try(ResultSet r=s.executeQuery()){while(r.next()){List<Object>row=new ArrayList<>();for(int i=1;i<=columns(q);i++)row.add(r.getString(i));out.add(row);}}}return out;}
 static void command(Connection c,String s)throws Exception{calls++;commands.add(s);try(Statement st=c.createStatement()){st.execute(s);}}
 static JSONObject props(Connection c,String id)throws Exception{return JSON.parseObject((String)sql(c,"SELECT props FROM anchors WHERE id=?",id).get(0).get(0)).getJSONObject("archetype");}
 static Set<String> neighbors(Connection c,Collection<String>f)throws Exception{Set<String>n=new LinkedHashSet<>();if(f.isEmpty())return n;for(List<Object>r:sql(c,"SELECT DISTINCT dst FROM adj_knows WHERE src IN("+marks(f.size())+")",f.toArray()))n.add((String)r.get(0));return n;}
 static JSONObject personFields(JSONObject p){JSONObject r=new JSONObject();for(String k:new String[]{"firstName","lastName","birthday","locationIP","browserUsed","gender","creationDate"})r.put(k,p.get(k));return r;}
 public static JSONObject request(Connection c,JSONObject in)throws Exception{calls=0;commands.clear();command(c,"START TRANSACTION READ ONLY");command(c,"SET SESSION innodb_lock_wait_timeout=10");try{if(regionBoundary!=null)regionBoundary.enter(c);JSONObject out=body(c,in);if(regionBoundary!=null)regionBoundary.leave(c);command(c,"COMMIT");return out;}catch(Exception e){command(c,"ROLLBACK");throw e;}}
 public static JSONObject body(Connection c,JSONObject in)throws Exception{
 JSONObject out=new JSONObject();String pid=in.containsKey("person_jid")?uuid(in.getString("person_jid")):null;
 if(query.equals("is1")){List<List<Object>>r=sql(c,"SELECT p.props,"+num("n","place_id")+" FROM anchors p LEFT JOIN anchors e ON e.src=p.id AND e.kind='EdgeAnchor' AND e.arch_type='IsLocatedIn' LEFT JOIN anchors n ON n.id=e.dst AND n.kind='NodeAnchor' AND n.arch_type='Place' WHERE p.id=? ORDER BY e.seq,e.id LIMIT 1",pid);out=personFields(JSON.parseObject((String)r.get(0).get(0)).getJSONObject("archetype"));out.put("cityId",r.get(0).get(1)==null?-1:Long.valueOf((String)r.get(0).get(1)));return out;}
 if(query.equals("is3")){List<JSONObject>outrows=new ArrayList<>();String projection=num("p","person_id")+","+j("p","firstName")+","+j("p","lastName");String q="SELECT "+projection+" FROM (SELECT e.dst id FROM anchors e WHERE e.src=? AND e.kind='EdgeAnchor' AND e.arch_type='Knows' UNION ALL SELECT e.src id FROM anchors e WHERE e.dst=? AND e.kind='EdgeAnchor' AND e.arch_type='Knows') f JOIN anchors p ON p.id=f.id AND p.kind='NodeAnchor' AND p.arch_type='Person' ORDER BY "+num("p","person_id");for(List<Object>r:sql(c,q,pid,pid)){JSONObject o=new JSONObject();o.put("personId",Long.valueOf((String)r.get(0)));o.put("firstName",r.get(1));o.put("lastName",r.get(2));outrows.add(o);}out.put("friends",outrows);out.put("count",outrows.size());return out;}
 if(finiteDepth&&query.equals("ic1"))return finiteIc1(c,in,pid);
 if(finiteDepth&&query.equals("ic13"))return finiteIc13(c,in);
 if(query.equals("ic13")||query.equals("ic1")){String start=query.equals("ic13")?uuid(in.getString("person1_jid")):pid;String target=query.equals("ic13")?uuid(in.getString("person2_jid")):null;Map<String,Integer>dist=new LinkedHashMap<>();dist.put(start,0);Set<String>front=new LinkedHashSet<>(Arrays.asList(start));int answer=start.equals(target)?0:-1;
 for(int d=1;d<=(query.equals("ic1")?3:6)&&answer<0;d++){Set<String>n=neighbors(c,front);n.removeAll(dist.keySet());for(String x:n)dist.put(x,d);if(target!=null&&n.contains(target)){answer=d;break;}if(n.isEmpty())break;front=n;}
 if(query.equals("ic13")){out.put("length",answer);return out;}dist.remove(start);List<JSONObject>found=new ArrayList<>();if(!dist.isEmpty()){List<Object>a=new ArrayList<>(dist.keySet());a.add(in.getString("first_name"));for(List<Object>r:sql(c,"SELECT p.id,p.person_id,p.last_name FROM jac_snb_person_mirror p WHERE p.id IN("+marks(dist.size())+") AND p.first_name=?",a.toArray())){JSONObject x=new JSONObject();x.put("personId",Long.valueOf((String)r.get(1)));x.put("lastName",r.get(2));x.put("distance",dist.get(r.get(0)));found.add(x);}}found.sort((a,b)->{int t=Integer.compare(a.getIntValue("distance"),b.getIntValue("distance"));if(t==0)t=a.getString("lastName").compareTo(b.getString("lastName"));if(t==0)t=Long.compare(a.getLongValue("personId"),b.getLongValue("personId"));return t;});out.put("people",found.subList(0,Math.min(20,found.size())));return out;}
 return messages(c,in,pid);
 }
 static JSONObject finiteIc1(Connection c,JSONObject in,String pid)throws Exception{
 List<Object>args=new ArrayList<>();List<String>branches=new ArrayList<>();for(int depth=1;depth<=3;depth++){StringBuilder q=new StringBuilder("SELECT k"+depth+".dst AS id,"+depth+" AS dist FROM adj_knows k1");for(int d=2;d<=depth;d++)q.append(" JOIN adj_knows k"+d+" ON k"+d+".src=k"+(d-1)+".dst");q.append(" WHERE k1.src=?");branches.add(q.toString());args.add(pid);}args.add(pid);args.add(in.getString("first_name"));String q="SELECT p.person_id,p.last_name,MIN(r.dist) AS distance FROM ("+String.join(" UNION ALL ",branches)+")r JOIN jac_snb_person_mirror p ON p.id=r.id WHERE p.id<>? AND p.first_name=? GROUP BY p.id,p.person_id,p.last_name ORDER BY MIN(r.dist),p.last_name,p.person_id LIMIT 20";List<JSONObject>found=new ArrayList<>();for(List<Object>r:sql(c,q,args.toArray())){JSONObject x=new JSONObject();x.put("personId",Long.valueOf((String)r.get(0)));x.put("lastName",r.get(1));x.put("distance",Integer.valueOf((String)r.get(2)));found.add(x);}JSONObject out=new JSONObject();out.put("people",found);return out;
 }
 static JSONObject finiteIc13(Connection c,JSONObject in)throws Exception{
 String src=uuid(in.getString("person1_jid")),dst=uuid(in.getString("person2_jid"));List<Object>args=new ArrayList<>();args.add(src);args.add(dst);StringBuilder q=new StringBuilder("SELECT CASE WHEN ?=? THEN 0");for(int depth=1;depth<=6;depth++){q.append(" WHEN EXISTS(SELECT 1 FROM adj_knows k1");for(int d=2;d<=depth;d++)q.append(" JOIN adj_knows k"+d+" ON k"+d+".src=k"+(d-1)+".dst");q.append(" WHERE k1.src=? AND k"+depth+".dst=?) THEN "+depth);args.add(src);args.add(dst);}q.append(" ELSE -1 END AS length");JSONObject out=new JSONObject();out.put("length",Integer.valueOf((String)sql(c,q.toString(),args.toArray()).get(0).get(0)));return out;
 }
 static JSONObject messages(Connection c,JSONObject in,String pid)throws Exception{
 boolean recent=query.equals("is2");String q;Object[]args;
 if(recent){q="SELECT m.id,m.arch_type,m.props,a.props,r.props,ra.props FROM jac_snb_message_mirror m LEFT JOIN jac_snb_person_mirror a ON a.id=m.creator_id LEFT JOIN jac_snb_message_mirror r ON r.id=m.root_of_replyof LEFT JOIN jac_snb_person_mirror ra ON ra.id=r.creator_id WHERE m.creator_id=? ORDER BY m.creation_date DESC,m.tie_id DESC LIMIT 10";args=new Object[]{pid};}
 else if(branchTopk){Set<String>friends=neighbors(c,Arrays.asList(pid));if(friends.isEmpty()){JSONObject empty=new JSONObject();empty.put("messages",new ArrayList<>());return empty;}List<String>branches=new ArrayList<>();List<Object>bindings=new ArrayList<>();for(String friend:friends)for(String type:new String[]{"Post","Comment"}){branches.add("(SELECT id,creation_date,tie_id FROM jac_snb_message_mirror WHERE creator_id=? AND arch_type='"+type+"' AND creation_date<=? ORDER BY creation_date DESC,tie_id ASC LIMIT 20)");bindings.add(friend);bindings.add(in.getLong("max_date"));}q="SELECT m.id,m.arch_type,m.props,a.props FROM (SELECT id,creation_date,tie_id FROM ("+String.join(" UNION ALL ",branches)+")candidates ORDER BY creation_date DESC,tie_id ASC LIMIT 20)best JOIN jac_snb_message_mirror m ON m.id=best.id JOIN jac_snb_person_mirror a ON a.id=m.creator_id ORDER BY best.creation_date DESC,best.tie_id ASC";args=bindings.toArray();}
 else{q="SELECT m.id,m.arch_type,m.props,a.props FROM adj_knows f JOIN jac_snb_message_mirror m ON m.creator_id=f.dst JOIN jac_snb_person_mirror a ON a.id=m.creator_id WHERE f.src=? AND m.creation_date<=? ORDER BY m.creation_date DESC,m.tie_id ASC LIMIT 20";args=new Object[]{pid,in.getLong("max_date")};}
 List<JSONObject>rows=new ArrayList<>();for(List<Object>r:sql(c,q,args)){boolean post=r.get(1).equals("Post");JSONObject p=JSON.parseObject((String)r.get(2)).getJSONObject("archetype"),a=r.get(3)==null?null:JSON.parseObject((String)r.get(3)).getJSONObject("archetype");JSONObject x=new JSONObject();x.put("id",p.get(post?"post_id":"comment_id"));x.put("creationDate",p.get("creationDate"));String content=p.getString("content");x.put("content",post&&(content==null||content.isEmpty())?p.get("imageFile"):content);
 if(recent){x.put("kind",post?"post":"comment");if(post){x.put("origPostId",p.get("post_id"));x.put("origAuthorId",a.get("person_id"));}else if(r.get(4)!=null){JSONObject rp=JSON.parseObject((String)r.get(4)).getJSONObject("archetype");x.put("origPostId",rp.get("post_id"));if(r.get(5)!=null)x.put("origAuthorId",JSON.parseObject((String)r.get(5)).getJSONObject("archetype").get("person_id"));}}
 else{x.put("authorId",a==null?null:a.get("person_id"));x.put("authorFirst",a==null?null:a.get("firstName"));x.put("authorLast",a==null?null:a.get("lastName"));}rows.add(x);}
 JSONObject out=new JSONObject();out.put("messages",rows);return out;
 }
 public static void main(String[]a)throws Exception{query=a[0];Path catalog=Paths.get(a[1]),out=Paths.get(a[2]);Files.createDirectory(out);JSONArray inputs=JSON.parseObject(new String(Files.readAllBytes(catalog),"UTF-8")).getJSONArray(query);try(Connection c=DriverManager.getConnection(System.getProperty("snb.url","jdbc:mysql://127.0.0.1:55337/jac_snb_six_20261020?useSSL=false&useUnicode=true&characterEncoding=UTF-8"),"root","")){for(Object value:inputs){JSONObject input=(JSONObject)value;long start=System.nanoTime();JSONObject result=request(c,input.getJSONObject("body"));JSONObject row=new JSONObject();row.put("idx",input.get("idx"));row.put("query",query);row.put("result",result);row.put("expected_canonical_sha256",input.get("expected_canonical_sha256"));row.put("ms",(System.nanoTime()-start)/1e6);row.put("source_calls",calls);row.put("sql",new ArrayList<>(commands));Files.write(out.resolve("rows.jsonl"),(row.toJSONString()+"\n").getBytes("UTF-8"),StandardOpenOption.CREATE,StandardOpenOption.APPEND);}}}
}
